const results    = $input.all();
const webhook    = $('Webhook').first().json.body;
const query      = webhook.query;
const mode       = webhook.mode || 'answer';
const grade      = webhook.grade || '';
const subject    = webhook.subject || '';
const studentName = webhook.studentName || 'Student';

// Build context from search results
let context = '';
let sources  = [];

if (results.length && results[0].json && results[0].json.content) {
  context = results
    .filter(r => r.json.similarity > 0.3)
    .slice(0, 4)
    .map((r, i) => `[Source ${i+1} - ${r.json.subject} Grade ${r.json.grade}]\n${r.json.content}`)
    .join('\n\n');

  sources = results
    .filter(r => r.json.similarity > 0.3)
    .map(r => r.json.filename)
    .filter((v, i, a) => a.indexOf(v) === i);
}

const hasContext = context.length > 50;

let prompt = '';

if (mode === 'quiz') {
  // Quiz generation prompt with curriculum context
  prompt = hasContext
    ? `You are generating a quiz for a school student based on their curriculum.

Student: ${studentName}
Grade: ${grade}
Subject: ${subject}

CURRICULUM CONTENT (use this to generate questions):
${context}

Generate exactly 5 multiple choice questions based on the curriculum content above.
Return ONLY this JSON, nothing else:
{
  "questions": [
    {
      "q": "Question text?",
      "a": "Option A",
      "b": "Option B",
      "c": "Option C",
      "d": "Option D",
      "correct": "a"
    }
  ]
}

Rules:
- Base questions directly on the curriculum content provided
- Make questions appropriate for Grade ${grade}
- correct field must be lowercase a, b, c, or d
- Return ONLY the JSON`
    : `Generate exactly 5 multiple choice questions about ${subject} for Grade ${grade} school student.
Return ONLY valid JSON with questions array. Each question needs q, a, b, c, d, correct fields.`;

} else {
  // Homework help prompt with curriculum context
  prompt = hasContext
    ? `You are a helpful tutor. Answer the student's question using their curriculum materials.

Student: ${studentName}
Question: ${query}

RELEVANT CURRICULUM CONTENT:
${context}

Instructions:
- Answer based on the curriculum content above
- Explain step by step in simple language
- If maths, show every calculation step
- Give a real-life example if helpful
- Keep response under 250 words
- End with one practice question
- Sources used: ${sources.join(', ')}`
    : `You are a helpful tutor. Answer this question step by step for a school student.
Question: ${query}
Keep response under 200 words. End with one practice question.`;
}

return [{
  json: {
    prompt:     prompt,
    hasContext: hasContext,
    mode:       mode,
    sources:    sources,
    ollamaBody: JSON.stringify({
      model:   'llama3.2:1b',
      prompt:  prompt,
      stream:  false,
      options: { num_predict: 600, temperature: 0.3 }
    })
  }
}];

const ollamaData  = $input.all()[0].json;
const ragData     = $('Build RAG Response').item.json;
const answer      = (ollamaData.response || '').trim();
const mode        = ragData.mode;

let reply = answer;

if (ragData.hasContext && ragData.sources.length) {
  const sourceNote = `\n\n📖 From: ${ragData.sources.join(', ')}`;
  if (mode !== 'quiz') reply += sourceNote;
}

return [{
  json: {
    reply:      reply,
    hasContext: ragData.hasContext,
    mode:       mode
  }
}];

